    public static bool operator >=(VolumeFlow a, UnknownUnit b) => SIComparison.GreaterOrEqual(a._si, b.SI);
    public static bool operator ==(UnknownUnit a, VolumeFlow b) => SIComparison.Equal(a.SI, b._si);
    public static bool operator !=(UnknownUnit a, VolumeFlow b) => !SIComparison.Equal(a.SI, b._si);
    public static bool operator <(UnknownUnit a, VolumeFlow b) => SIComparison.Less(a.SI, b._si);
    public static bool operator >(UnknownUnit a, VolumeFlow b) => SIComparison.Greater(a.SI, b._si);
    public static bool operator <=(UnknownUnit a, VolumeFlow b) => SIComparison.LessOrEqual(a.SI, b._si);
    public static bool operator >=(UnknownUnit a, VolumeFlow b) => SIComparison.GreaterOrEqual(a.SI, b._si);
    // Nullable: same semantics as the lifted operators (null compares false, == only when both have a value)
    public static bool operator ==(VolumeFlow? a, VolumeFlow b) => a.HasValue && a.GetValueOrDefault() == b;
    public static bool operator !=(VolumeFlow? a, VolumeFlow b) => !(a == b);
    public static bool operator ==(VolumeFlow a, VolumeFlow? b) => b.HasValue && a == b.GetValueOrDefault();
    public static bool operator !=(VolumeFlow a, VolumeFlow? b) => !(a == b);
    public static bool operator ==(VolumeFlow? a, VolumeFlow? b) => a.HasValue ? b.HasValue && a.GetValueOrDefault() == b.GetValueOrDefault() : !b.HasValue;
    public static bool operator !=(VolumeFlow? a, VolumeFlow? b) => !(a == b);
    public static bool operator <(VolumeFlow? a, VolumeFlow b) => a.HasValue && a.GetValueOrDefault() < b;
    public static bool operator >(VolumeFlow? a, VolumeFlow b) => a.HasValue && a.GetValueOrDefault() > b;
    public static bool operator <=(VolumeFlow? a, VolumeFlow b) => a.HasValue && a.GetValueOrDefault() <= b;
    public static bool operator >=(VolumeFlow? a, VolumeFlow b) => a.HasValue && a.GetValueOrDefault() >= b;
    public static bool operator <(VolumeFlow a, VolumeFlow? b) => b.HasValue && a < b.GetValueOrDefault();
    public static bool operator >(VolumeFlow a, VolumeFlow? b) => b.HasValue && a > b.GetValueOrDefault();
    public static bool operator <=(VolumeFlow a, VolumeFlow? b) => b.HasValue && a <= b.GetValueOrDefault();
    public static bool operator >=(VolumeFlow a, VolumeFlow? b) => b.HasValue && a >= b.GetValueOrDefault();

    // ---- Conversions ----
    public static implicit operator UnknownUnit(VolumeFlow value) => new(value._si);
    /// <summary>Free at runtime - the analyzer checks the dimension at compile time (EUF0001).</summary>
    public static implicit operator VolumeFlow(UnknownUnit value) => new(value.SI);
    // Deliberately NO implicit VolumeFlow(UnknownUnit?): the null literal converts to UnknownUnit?, so "Power p = null;" would
    // compile and throw, and "cond ? x : null" would throw instead of being null. (The analyzer caught this.)

    // ---- Helpers - same names and behaviour as EngineeringUnits ----
    public VolumeFlow Abs() => new(Math.Abs(_si));
    /// <summary>Limits the value to [min, max]. Like EngineeringUnits: if max &lt; min the value is returned unchanged.</summary>
    public VolumeFlow Clamp(VolumeFlow min, VolumeFlow max) => max._si < min._si ? this : new(Math.Min(Math.Max(_si, min._si), max._si));
    /// <summary>Like EngineeringUnits: a null limit is no limit.</summary>
    public VolumeFlow Clamp(VolumeFlow? min, VolumeFlow? max) => (min, max) switch
    {
        (null, null) => this,
        (null, { } hi) => _si > hi._si ? hi : this,
        ({ } lo, null) => _si < lo._si ? lo : this,
        ({ } lo, { } hi) => Clamp(lo, hi),
    };
    public VolumeFlow LowerLimitAt(VolumeFlow limit) => _si > limit._si ? this : limit;
    public VolumeFlow UpperLimitAt(VolumeFlow limit) => _si < limit._si ? this : limit;
    /// <summary>Rounds to a multiple of <paramref name="step"/> (midpoints to even, like Math.Round).</summary>
    public VolumeFlow RoundTo(VolumeFlow step) => new(Math.Round(_si / step._si) * step._si);
    public VolumeFlow CeilingTo(VolumeFlow step) => new(Math.Ceiling(_si / step._si) * step._si);
    public VolumeFlow FloorTo(VolumeFlow step) => new(Math.Floor(_si / step._si) * step._si);
    public bool IsZero() => _si == 0;
    public bool IsNotZero() => !IsZero();
    public bool IsAboveZero() => _si > 0;
    public bool IsBelowZero() => _si < 0;
    /// <summary>Not NaN and not infinite, like EngineeringUnits.</summary>
    public bool HasValue() => !double.IsNaN(_si) && !double.IsInfinity(_si);
    public bool HasNoValue() => !HasValue();
    /// <summary>A VolumeFlow is never null - returns itself. The VolumeFlow? version returns Zero for null.</summary>
    public VolumeFlow IfNullSetToZero() => this;
    public static VolumeFlow Min(VolumeFlow a, VolumeFlow b) => a._si <= b._si ? a : b;
    public static VolumeFlow Max(VolumeFlow a, VolumeFlow b) => a._si >= b._si ? a : b;
    /// <summary>
    /// == with your own tolerance. == itself already allows 1e-12 (relative), so 1 ft == 12 in is true
    /// even though the doubles differ in the last bit.
    /// </summary>
    public bool IsCloseTo(VolumeFlow other, double relativeTolerance = SIComparison.RelativeTolerance)
        => SIComparison.Equal(_si, other._si, relativeTolerance);
    public bool IsNaN() => double.IsNaN(_si);
    public bool IsInfinity() => double.IsInfinity(_si);

    // ---- Equality ----
    public bool Equals(VolumeFlow other) => _si.Equals(other._si);
    public override bool Equals(object? obj) => obj is VolumeFlow other && Equals(other);
    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(VolumeFlow other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is VolumeFlow other ? CompareTo(other) : throw new ArgumentException($"Can't compare VolumeFlow with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, VolumeFlowUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(VolumeFlowUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to VolumeFlow, but math on it needs the VolumeFlow first.
    /// </summary>
    public QuantityInUnit<VolumeFlow> ToUnit(VolumeFlowUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public VolumeFlow ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "m³/s"}. Reads that (any unit of VolumeFlow, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class VolumeFlowJsonConverter : JsonConverter<VolumeFlow>
{
    public override VolumeFlow Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => VolumeFlow.FromSI(QuantityJson.Read(ref reader, "VolumeFlow", VolumeFlowUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, VolumeFlow value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, VolumeFlowUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this VolumeFlow value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this VolumeFlow value) => new(Math.Sqrt(value.SI));

    public static VolumeFlow Sum(this IEnumerable<VolumeFlow> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return VolumeFlow.FromSI(sum);
    }

    public static VolumeFlow Average(this IEnumerable<VolumeFlow> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : VolumeFlow.FromSI(sum / count);
    }

    public static VolumeFlow Min(this IEnumerable<VolumeFlow> values) => Aggregate(values, Math.Min);
    public static VolumeFlow Max(this IEnumerable<VolumeFlow> values) => Aggregate(values, Math.Max);

    private static VolumeFlow Aggregate(IEnumerable<VolumeFlow> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return VolumeFlow.FromSI(result);
    }
}
